UNITS=[]; ITEMS=[]
def unit(subject,title,goals,source):
    u={'subject':subject,'title':title,'goals':goals,'source':source,'items':[]}; UNITS.append(u);return u
def q(u,goal,title,prompt,answer,observe,nextcheck,mode='말·글',material='',script='',drawing=''):
    n=sum(x['subject']==u['subject'] for x in ITEMS)+1
    item={'id':f"{u['subject']}-{n:02d}",'subject':u['subject'],'unit':u['title'],'goal':goal,'title':title,'prompt':prompt,'answer':answer,'observe':observe,'nextCheck':nextcheck,'mode':mode,'material':material,'guardianScript':script,'drawing':drawing,'source':u['source']}
    ITEMS.append(item);u['items'].append(item['id']);return item

# 국어: EBS 공식 강의 설명의 핵심 학습 활동을 직접 대조하여 구성.
u=unit('국어','1. 경험과 관련지으며 이해해요',['경험과 작품 연결','중요한 내용 간추리며 듣기','들은 이야기 글로 정리'],'K')
q(u,u['goals'][0],'이야기와 내 경험','이야기를 읽고 답해 보세요.\n① 민서의 마음이 어떻게 달라졌나요? 글에서 근거를 찾아 말해 주세요.\n② 비슷한 경험이 있나요? 그 경험이 민서의 마음을 이해하는 데 어떻게 도움이 되었나요? 없다면 비슷한 상황을 상상해 설명해도 괜찮아요.','처음에는 창피하거나 위축되었으나 친구의 도움으로 안심하고 다시 해 볼 용기를 얻음. 마음의 변화를 행동·말과 연결하고 자신의 경험 또는 상상과 비교.','자기 경험만 말하고 글의 근거를 놓치는지 분리해 관찰. 실제 경험 유무를 이해 수준으로 판정하지 않음.','학교에서 읽은 다른 이야기의 인물 마음과 자기 경험을 연결하여 다시 설명.',material='민서는 발표할 그림을 집에 두고 왔다. 친구들 앞에서 고개를 숙였다. 지우가 “칠판에 그려서 설명해도 돼.”라고 말했다. 민서는 칠판에 그림을 그리며 설명했다. 발표가 끝나자 민서는 “다음에는 준비물을 미리 챙길게. 그래도 오늘 다시 해 봐서 기뻐.”라고 말했다.')
q(u,u['goals'][1],'들은 안내의 중심 내용','보호자가 읽어 주는 안내를 들어 보세요.\n① 무엇을 알리는 안내인가요?\n② 꼭 기억해야 할 내용을 두 가지 이상 말해 주세요.\n③ 안내와 관계없는 내용은 무엇이었나요?','금요일 책 나눔 행사 안내. 장소는 교실, 책 1권, 겉표지에 이름, 학교 시작 전 책상에 놓기 중 중요한 내용. 화분의 새 잎은 행사와 무관.','학생에게 대본을 먼저 보여 주지 않음. 1회 들은 뒤 재청취 요청이 있으면 같은 대본을 다시 읽고 횟수 기록. 듣기 결과를 독립 읽기로 기록하지 않음.','학교 안내 하나를 듣고 무엇·언제·어디·준비할 것을 메모.',mode='듣고 말하기',script='이번 금요일, 우리 교실에서 책 나눔 행사를 합니다. 친구에게 소개하고 싶은 책 한 권을 가져오세요. 겉표지 안쪽에 자기 이름을 써 주세요. 학교가 시작되기 전에 책을 자기 책상 위에 놓으면 됩니다. 참고로 어제 교실 화분에 새 잎이 났습니다.')
q(u,u['goals'][2],'들은 이야기를 글로 정리','보호자가 읽어 주는 이야기를 듣고, 중요한 일이 드러나도록 3~4문장으로 정리해 보세요. 세부 내용을 모두 옮길 필요는 없어요.','서준이의 고장 난 자전거 발견 → 보호자에게 알림 → 함께 수리점 방문 → 수리 뒤 안전 확인의 흐름을 중요한 내용 중심으로 정리.','실제 쓰기를 관찰. 받아 적거나 말로만 답하면 쓰기는 미확인. 세부 숫자 기억보다 이야기의 중요 사건과 연결을 살핌.','다른 짧은 이야기를 듣고 중요한 사건 3개를 적어 글로 연결.',mode='듣고 쓰기',script='서준이는 자전거를 타려다가 브레이크가 잘 움직이지 않는 것을 발견했습니다. 그대로 타지 않고 아빠에게 알렸습니다. 두 사람은 자전거 수리점에 갔습니다. 수리한 뒤 서준이는 브레이크가 작동하는지 확인하고 안전모를 썼습니다. 수리점 벽에는 파란 시계가 있었습니다.')
u=unit('국어','2. 유창하게 읽고 발표해요',['유창한 읽기 점검','장면·분위기를 살려 읽기','글·그림으로 설명·발표'],'K')
q(u,u['goals'][0],'뜻이 잘 들리게 읽기','글을 소리 내어 읽어 보세요.\n① 어디에서 쉬어 읽으면 뜻이 잘 전달될까요? 표시해 보세요.\n② 스스로 다시 읽고 싶은 부분을 골라 한 번 더 읽어 보세요.','의미 단위와 문장 부호에 맞추어 끊어 읽기. 책/한 권을/가져왔습니다 등을 자연스럽게 읽음.','읽기 속도 경쟁 금지. 글자 정확성·의미 단위·자기 수정 각각 기록. 읽어 준 글을 따라 읽으면 도움 수행으로 남김.','학교 지문 3~4문장을 읽고 뜻이 달라지지 않게 끊어 읽는지 재확인.',mode='실제 읽기',material='오늘 우리 반은 책 나눔 행사를 했습니다. 나는 동물 이야기가 담긴 책 한 권을 가져왔습니다. 친구는 책을 받아 들고 웃었습니다. 내 책이 새로운 친구를 만난 것 같았습니다.')
q(u,u['goals'][1],'장면의 분위기를 살려 읽기','짧은 대화를 읽고 실제 목소리로 표현해 보세요.\n① 두 사람의 마음에 맞게 읽어 주세요.\n② 어떤 말을 강조하거나 목소리를 바꾸었나요? 그렇게 읽은 까닭도 말해 주세요.','첫 문장은 놀람·반가움, 두 번째는 걱정 후 안도의 분위기 등 글의 상황과 연결. 다양한 표현 수용.','과장된 연기나 특정 억양을 정답으로 요구하지 않음. 장면 이해와 실제 낭독을 함께 확인.','다른 대화에서 인물 마음을 먼저 말하고 목소리로 표현.',mode='실제 읽기',material='“찾았다! 내 운동화가 여기 있었네!”\n“다행이야. 아까는 잃어버린 줄 알고 걱정했어.”')
q(u,u['goals'][2],'그림을 보며 설명하기','처음 온 친구에게 우리 집에서 가까운 도서관이나 학교 안의 장소를 소개해 보세요.\n① 간단한 그림과 핵심 낱말을 준비해 주세요.\n② 그림을 가리키며 위치·하는 일·이용할 때 필요한 점을 설명해 주세요.\n③ 듣는 사람이 궁금해한 점에 답해 주세요.','그림·낱말과 말의 내용이 연결되고, 듣는 사람이 이해할 순서로 위치·용도·주의점을 설명.','잘 그리는 능력은 평가하지 않음. 그림만 만들고 발표하지 않으면 발표 미확인. 보호자는 실제 한 가지 질문만 하고 답을 기록.','학교 수업 그림을 보고 무엇을 보여 주는지 3문장으로 설명.',mode='그리기·발표',drawing='blank')
u=unit('국어','3. 정확하게 글을 써요',['자료 출처 확인','이어 주는 말','순서·방법 설명하는 글'],'K')
q(u,u['goals'][0],'자료의 출처 살피기','두 안내를 보고 답해 주세요.\n① 내일 도서관이 여는지 알아보려면 어느 자료를 먼저 확인할까요?\n② 자료를 이용하기 전에 무엇을 더 살펴봐야 할까요?\n③ 글에 자료의 출처를 밝혀 놓으면 어떤 점이 좋을까요?','공식 도서관 운영 안내를 우선 확인하고 날짜·해당 도서관·최신 변경 공지를 확인. 출처는 누가·언제 만든 정보인지 확인하고 원자료를 찾는 데 도움.','공식 출처이면 언제나 옳다고 단정하지 않도록 최신성 확인도 관찰. 출처 이름 암기만으로 충족하지 않음.','학교 글 한 편에서 자료를 만든 곳과 날짜를 찾아 신뢰 여부 설명.',material='자료 A: 구립도서관 운영 안내, 2026년 10월 8일 게시. “매주 월요일 휴관.”\n자료 B: 글쓴이와 날짜가 없는 메시지. “도서관은 매일 열어요.”\n가정: 오늘은 일요일이고 내일은 월요일입니다.')
q(u,u['goals'][1],'문장을 알맞게 연결하기','빈칸에 알맞은 말을 넣고 까닭을 설명해 주세요.\n① 비가 왔다. (그래서 / 그러나) 운동장 놀이가 취소되었다.\n② 비가 왔다. (그래서 / 그러나) 우리는 실내에서 즐겁게 놀았다.\n③ 두 말을 하나씩 사용하여 짧은 글을 써 보세요.','① 그래서(원인·결과), ② 그러나(앞 내용과 대비). 자기 문장에서도 관계가 자연스러움.','단어 선택·이유·자기 문장 적용을 나누어 확인. 선택만 맞고 문장 관계를 설명하지 못하면 일부 확인.','학교 설명 글에서 이어 주는 말 앞뒤의 관계 설명.',mode='쓰기·설명')
q(u,u['goals'][2],'처음 하는 친구에게 방법 설명하기','종이비행기 접기, 식물에 물 주기, 책 빌리기 중 하나를 고르세요. 처음 해 보는 친구가 따라 할 수 있게 4~6문장으로 방법을 써 보세요. 준비할 것과 순서가 드러나게 쓰고, 빠진 과정이 없는지 읽으며 고쳐 보세요.','준비물·먼저/다음/마지막 순서·구체적인 행동을 포함. 문장이 정확하고 과정이 빠지지 않아 실제 따라 할 수 있음.','맞춤법만으로 판단하지 않음. 보호자가 문장을 완성해 주면 독립 쓰기와 구분. 아이가 스스로 고친 부분 기록.','학교에서 배운 활동 방법을 다른 친구에게 설명하는 글 작성.',mode='실제 쓰기')
u=unit('국어','4. 서로 존중하며 대화해요',['높임 표현의 상황','바른 높임 표현 사용','상황에 맞는 대화 예절'],'K')
q(u,u['goals'][0],'누구에게 어떻게 말할까요?','같은 내용을 친구와 선생님에게 말하려고 해요.\n① “이것 좀 봐.”를 친구에게, 선생님에게 각각 어떻게 말하면 좋을까요?\n② 말하는 방식이 달라지는 까닭은 무엇인가요?','친구에게 자연스러운 말, 선생님에게 이것 좀 봐 주세요/보아 주시겠어요 등 상황에 맞는 높임. 상대·관계·상황 설명.','친구에게 존댓말을 사용해도 틀리지 않음. 특정 문장을 그대로 재현해야 한다고 요구하지 않음.','학교에서 만나는 두 상대에게 부탁하는 말을 각각 표현.',mode='말하기')
q(u,u['goals'][1],'높임 표현 고쳐 말하기','어른께 말하는 상황이에요. 더 알맞게 고쳐 말하고 이유를 알려 주세요.\n① “할머니가 밥 먹어.”\n② 선생님께 “내가 이것을 줄게.”\n③ 고친 표현으로 보호자와 한 번 대화해 보세요.','할머니께서 진지를 드세요/드십니다. 선생님께 제가 이것을 드릴게요 등 상대와 주체에 맞는 높임.','종결어미만 바꾸는지, 먹다→드시다/진지, 주다→드리다의 쓰임을 구별하는지 살핌. 배운 표현 범위 안에서 확인.','배운 높임말을 사용해 학교생활의 부탁·감사 대화.',mode='실제 대화')
q(u,u['goals'][2],'의견이 달라도 존중하며 대화하기','친구는 공놀이를, 나는 책 읽기를 하고 싶어요. 보호자가 친구 역할을 할 거예요.\n① 친구의 말을 끝까지 듣고 그 생각을 확인해 주세요.\n② 내 생각과 이유를 말해 주세요.\n③ 함께 정할 수 있는 방법을 제안해 주세요.','경청·상대 의견 확인·내 의견과 이유·번갈아 하기 등 존중하는 제안. 동의하지 않아도 됨.','예절의 이름만 설명하는 것과 실제 대화를 구분. 두 사람의 말을 주고받는 수행을 관찰.','가족 활동을 정할 때 서로의 말을 확인하고 합의 시도.',mode='역할 대화',script='친구 역할: “나는 오늘 공놀이를 하고 싶어. 몸을 움직이면 신날 것 같아.” 아이가 제안하면 “나는 책 읽기는 조금 지루할 것 같은데, 어떻게 하면 둘 다 즐거울까?”라고 말한다. 해결책은 미리 제시하지 않는다.')
u=unit('국어','5. 사전으로 여는 세상',['낱말의 종류·분류','형태가 바뀌는 낱말','국어사전 활용'],'K')
q(u,u['goals'][0],'기준을 세워 낱말 분류하기','학교, 달리다, 예쁘다, 연필, 먹다, 크다를 뜻의 특징에 따라 세 무리로 나누고, 각 무리의 기준을 말해 주세요. 같은 기준으로 낱말 하나씩 더 찾아 보세요.','이름: 학교·연필, 움직임: 달리다·먹다, 상태/성질: 예쁘다·크다. 각 기준에 맞는 추가 예.','품사 용어 암기보다 기준과 낱말의 뜻을 연결하는지 확인. 다른 타당한 분류는 기준을 확인하여 기록.','학교 글에서 이름·움직임·상태를 나타내는 낱말 찾기.')
q(u,u['goals'][1],'모양이 바뀌어도 같은 낱말','문장에 쓰인 낱말을 사전에서 찾으려 해요.\n① “어제 많이 걸었다.”의 걸었다는 어떤 형태로 찾을까요?\n② “꽃이 아름다워요.”의 아름다워요는 어떤 형태로 찾을까요?\n③ 찾을 때 문장 속 모양과 달라지는 까닭을 말해 주세요.','걷다, 아름답다. 문장에 쓰일 때 모양이 달라지고 사전의 기본형으로 찾음.','기본형을 맞히는 것과 변화 설명을 분리. 학교에서 기본형을 배우지 않았다면 미학습.','교과서의 바뀐 낱말 2개를 기본형으로 바꾸어 실제 사전 검색.')
q(u,u['goals'][2],'사전으로 문장의 뜻 알아보기','종이 또는 전자 국어사전을 실제로 사용해 보세요.\n① “아이들은 책상에 둘러앉아 의견을 나누었다.”에서 의견을 찾아 뜻을 말해 주세요.\n② “나뭇가지가 가늘다.”에서 가늘다를 찾아 이 문장에 맞는 뜻을 골라 주세요.\n③ 두 낱말 중 하나로 새 문장을 만들어 주세요.','의견: 어떤 대상에 대한 생각 등. 가늘다: 길이에 비해 굵기가 작다 등 문맥에 맞는 뜻. 사전의 설명을 자기 말·예문에 적용.','실제 찾기와 읽어 준 풀이 이해를 구분. 사전 화면의 여러 뜻 중 문맥에 맞는 뜻을 고르는지 확인.','교과서에서 낯선 낱말 하나를 사전으로 찾아 문맥 설명.',mode='사전 활용')
u=unit('국어','6. 감상과 표현의 즐거움',['작품의 재미·감동','의견과 이유 쓰기','의견 글 고쳐 쓰기'],'K')
q(u,u['goals'][0],'재미와 감동의 까닭','학교에서 본 만화 영화나 드라마 중 한 작품을 골라 주세요.\n① 작품 이름과 기억나는 장면을 말해 주세요.\n② 재미있거나 감동적이었던 까닭을 그 장면과 연결해 설명해 주세요.\n③ 다른 사람이 나와 다르게 느낄 수 있을까요? 왜 그럴까요?','특정 장면·인물·표현을 근거로 느낌 설명. 사람마다 경험·관점이 달라 감상이 다를 수 있음.','작품을 떠올리지 못하면 익숙한 작품을 함께 본 뒤 확인하고 조건 기록. 줄거리 기억만으로 감상 충족하지 않음.','학교 작품의 다른 장면에서 느낌과 근거를 연결.',mode='말하기')
q(u,u['goals'][1],'의견이 드러나게 쓰기','우리 반에서 함께 볼 만화 영화나 읽을 책을 하나 추천하려고 해요. 의견과 이유가 분명하게 드러나도록 4~5문장으로 써 보세요. 작품의 내용이나 표현에서 이유를 찾아 주세요.','추천 의견·작품에서 찾은 이유·마무리가 연결. 단순히 재미있다를 넘어서 장면·내용으로 설명.','정답 작품 없음. 의견과 이유의 연결을 관찰하고 맞춤법은 별도로 기록.','다른 작품이나 학급생활 주제에 의견·이유 쓰기.',mode='실제 쓰기')
q(u,u['goals'][2],'읽는 사람을 생각하며 고치기','다음 글은 추천하는 까닭이 잘 드러나나요?\n① 부족한 점 두 가지를 말해 주세요.\n② 의견과 이유가 잘 이어지도록 3~4문장으로 고쳐 써 주세요.\n③ 무엇을 왜 고쳤는지 말해 주세요.','책 제목·추천 이유가 불명확하고 관계없는 날씨가 섞임. 작품의 내용·표현에 근거한 이유를 넣고 관계없는 내용 삭제.','실제 책 내용을 모르면 가상의 제목·장면을 만들어도 된다고 안내. 내용의 사실성 검사가 아닌 글 구성·수정 확인.','자기가 쓴 앞 문항 글을 같은 기준으로 고치기.',mode='고쳐 쓰기',material='나는 이 책을 추천합니다. 아주 좋기 때문입니다. 오늘 날씨가 맑습니다. 모두 이 책을 읽으면 좋겠습니다.')

