def esc(t):return html.escape(t).replace('\n','<br/>')
def paragraph(c,text,x,y,width,size=11,leading=None,color=INK):
    st=ParagraphStyle('p',fontName='Korean',fontSize=size,leading=leading or size*1.55,textColor=color,wordWrap='CJK',spaceAfter=0)
    p=Paragraph(esc(text),st);pw,ph=p.wrap(width,2000);p.drawOn(c,x,y-ph);return y-ph
def rule(c,y,x=44,width=W-88):
    c.setStrokeColor(BORDER);c.setLineWidth(.45);c.line(x,y,x+width,y)
def frame(c,label,num):
    c.setFillColor(INK);c.setFont('Korean',9);c.drawString(44,H-30,'한눈육아 | 초3 2학기 교과 이해 확인 | codex')
    c.setFont('Korean',8);c.drawRightString(W-44,26,f'{label} · {num}');rule(c,H-39)
def new_page(c,label,num,title,subtitle=''):
    frame(c,label,num);y=paragraph(c,title,44,H-56,W-88,19)
    if subtitle:y=paragraph(c,subtitle,44,y-9,W-88,9.5)
    return y-18
def boxlines(c,y,count=2,width=W-116):
    for j in range(count):rule(c,y-j*19,58,width)
def draw_asset(c,kind,y):
    c.setFillColor(INK)
    if kind=='circle':
        cx=170;cy=y-49;r=40;c.setStrokeColor(INK);c.circle(cx,cy,r)
        c.line(cx-r,cy,cx+r,cy);c.line(cx,cy,cx,cy+r)
        c.setFont('Korean',10)
        for t,x,z in [('A',cx-r-13,cy-4),('B',cx+r+4,cy-4),('C',cx-4,cy+r+5),('O',cx+4,cy-13)]:c.drawString(x,z,t)
        return y-100
    if kind=='graph':
        c.setStrokeColor(INK);c.setLineWidth(.8)
        c.setFont('Korean',10);c.drawString(58,y-12,'책 대출 수 | 큰 네모 1개 = 10권, 작은 네모 1개 = 1권')
        for j,(title,big,small) in enumerate([('동화',3,2),('과학',2,4),('역사',1,5)]):
            cy=y-40-j*23;c.drawString(58,cy,title)
            for k in range(big):c.rect(112+k*18,cy-1,12,12,stroke=1,fill=0)
            for k in range(small):c.rect(190+k*10,cy+2,5,5,stroke=1,fill=0)
        return y-109
    return y

def build_student():
    p=OUT/'초3-2-EBS기준-교과이해-아이용질문지-codex.pdf';c=canvas.Canvas(str(p),pagesize=A4);c.setTitle('초3 2학기 교과 이해 아이용 질문지 codex');num=1
    y=new_page(c,'아이용',num,'학교에서 배운 내용을 설명해 볼까요?','2026년판 EBS 만점왕 국어·수학·사회·과학 중심 | 영어는 학교 대조용 보완')
    y=paragraph(c,'이름: ____________________     시작일: ____________________\n학교 교과서 / 배운 단원: __________________________________',44,y,W-88,12)
    y=paragraph(c,'이 질문지는 점수를 매기는 시험이 아니에요. 학교에서 배운 내용을 내가 어떻게 이해했는지 알아보는 활동이에요.',44,y-24,W-88,13)
    for t in ['1. 한 번에 한 과목의 배운 단원만 골라요. 하루에 3~6문항씩 나누어 해도 좋아요.','2. 아는 내용은 답과 함께 “왜 그렇게 생각했는지” 알려 주세요.','3. 쓰기·그리기·읽기·대화라고 적힌 활동은 실제로 해 보세요.','4. 아직 배우지 않았거나 피곤하면 표시하고 멈춰도 괜찮아요.','5. 보호자가 도와주었다면 어떤 도움을 썼는지 기록해요.']:
        y=paragraph(c,t,44,y-18,W-88,11.5)
    y=paragraph(c,'문항 옆 기록: 독립 설명 / 도움 후 설명 / 다시 확인 / 미학습 / 미실시\n정답과 보호자용 읽기 대본은 별도 보호자용 파일에 있어요.',44,y-24,W-88,10)
    y=paragraph(c,'과목별 문항: 국어 18 · 수학 18 · 사회 10 · 과학 14 · 영어 12 = 72문항\n여러 소질문을 포함합니다. 모두 한 번에 풀지 않아요.\n영어는 학교에서 실제로 배운 주제·표현에만 답해요.',44,y-18,W-88,10)
    c.showPage()
    for u in UNITS:
        its=[i for i in ITEMS if i['id'] in u['items']]
        # 2 per page guarantees writing and drawing space, especially long prompts.
        for a in range(0,len(its),2):
            num+=1;y=new_page(c,'아이용',num,f"{u['subject']} | {u['title']}",'날짜: __________   학교에서: [ ] 배웠어요  [ ] 아직 안 배웠어요  [ ] 확인 필요')
            top=y
            for j,i in enumerate(its[a:a+2]):
                by=top-j*335;c.setFillColor(LIGHT);c.roundRect(44,by-312,W-88,312,8,stroke=0,fill=1)
                z=paragraph(c,f"{i['id']}  {i['title']}",58,by-12,W-116,12.5)
                z=paragraph(c,f"활동: {i['mode']}",58,z-3,W-116,8.5,color=ACCENT)
                if i['material']:z=paragraph(c,i['material'],58,z-8,W-116,10.5)
                if i['drawing'] in ['circle','graph']:z=draw_asset(c,i['drawing'],z-3)
                z=paragraph(c,i['prompt'],58,z-8,W-116,11)
                bottom=by-285
                if z<bottom+16:raise ValueError(f"Student overflow {i['id']} at {z}, {bottom}")
                if i['drawing']=='blank':
                    avail=z-bottom-10;c.setStrokeColor(BORDER);c.roundRect(58,bottom+5,W-116,avail,4,stroke=1,fill=0)
                else:
                    # Remaining space is deliberately open for calculations and written answers.
                    lines=max(1,min(4,int((z-bottom-17)/19)));boxlines(c,z-17,lines)
                paragraph(c,'기록: [ ] 독립 설명  [ ] 도움 후 설명  [ ] 다시 확인  [ ] 미학습  [ ] 미실시',58,by-293,W-116,8)
            c.showPage()
    c.save();return p,num

