        y=paragraph(c,'독립 설명이 확인된 문항/근거: ____________________________________\n다시 확인할 문항/내용/도움: ______________________________________\n다음 행동(교과서·EBS 복습/교사 질문)과 날짜: ________________________',44,y-7,W-88,9.5);rule(c,y-7);y-=14
