def asset_html(kind):
    if kind=='circle':return '<svg width="220" height="110" viewBox="0 0 220 110"><circle cx="100" cy="57" r="35" fill="none" stroke="black"/><path d="M65 57H135M100 57V22" stroke="black"/><text x="50" y="62">A</text><text x="139" y="62">B</text><text x="96" y="17">C</text><text x="104" y="73">O</text></svg>'
    if kind=='graph':return '<p>大ネモ 1개=10권, 작은 네모 1개=1권</p>'.replace('大ネモ','큰 네모')+'<p>동화: □ □ □ ▫ ▫<br>과학: □ □ ▫ ▫ ▫ ▫<br>역사: □ ▫ ▫ ▫ ▫ ▫</p>'
    return ''
CSS='''body{font-family:"Arial Unicode MS","Apple SD Gothic Neo",sans-serif;color:#24252a;background:#f4f3f1;line-height:1.65;margin:0}main{max-width:900px;margin:auto;padding:30px}h1{font-size:26px}h2{font-size:21px}h3{font-size:17px;margin:0 0 6px}article,section{background:white;border:1px solid #bbb;border-radius:12px;padding:22px;margin:18px 0}small{color:#645f58}.material{background:#f4f3f1;padding:12px;border-left:3px solid #c34a0c}.answer-space{height:110px;border-bottom:1px solid #aaa;margin:12px 0}.draw-space{height:150px;border:1px solid #aaa}.tools{position:sticky;top:0;background:#ffe2d0;padding:14px}button,select{font:inherit;padding:8px}table{border-collapse:collapse;width:100%;font-size:13px}td,th{border:1px solid #aaa;padding:8px;text-align:left}textarea{width:98%;font:inherit;border:1px solid #bbb}a{color:#a53e09}@page{size:A4;margin:15mm}@media print{body{background:white;font-size:11pt}main{padding:0}.tools{display:none}article{break-inside:avoid;border-radius:0;margin:10px 0;padding:12px}h2{break-before:page}h1,h2,h3{break-after:avoid}a{color:inherit}textarea{border:0}section{break-inside:avoid}small{color:#444}}'''
def build_html(guardian=False):
    title='보호자용 답과 관찰' if guardian else '아이용 질문지'
    name='초3-2-EBS기준-교과이해-'+('보호자용답과관찰' if guardian else '아이용질문지')+'-codex.html'
    s=['<!doctype html><html lang="ko"><meta charset="utf-8"><title>'+title+' codex</title><style>'+CSS+'</style><div class="tools"><button onclick="window.print()">인쇄 / PDF 저장</button> <label>과목 <select id="subject"><option>전체</option>'+''.join('<option>'+v+'</option>' for v in ['국어','수학','사회','과학','영어'])+'</select></label></div><main><h1>초3 2학기 교과 이해 확인 | '+title+' | codex</h1><p>2026년판 EBS 만점왕 4과목 중심 · 영어 학교 대조용 보완 · 총 72문항</p><p>한 번에 배운 단원의 3~6문항만 진행하세요. 답과 이유를 함께 확인하며 미학습·미실시는 별도로 표시합니다. 보호자용 PDF에 사용 방법과 목표 연결표가 있습니다.</p>']
    if not guardian:s.append('<p>이름: ____________________ 날짜: ____________________<br>학교 교과서·배운 단원: __________________________________</p>')
    for u in UNITS:
        s.append('<div class="unit" data-subject="'+u['subject']+'"><h2>'+esc(u['subject']+' | '+u['title'])+'</h2>')
        for i in [v for v in ITEMS if v['id'] in u['items']]:
            s.append('<article><h3>'+esc(i['id']+' '+i['title'])+'</h3><small>'+esc(i['mode'])+'</small>')
            if guardian:
                for label,key in [('목표','goal'),('수용 답·핵심','answer'),('관찰·해석 제한','observe'),('다음 확인','nextCheck'),('보호자 전용 대본','guardianScript')]:
                    if i[key]:s.append('<p><b>'+label+'</b> '+esc(i[key])+'</p>')
            else:
                if i['material']:s.append('<div class="material">'+esc(i['material'])+'</div>')
                s.append(asset_html(i['drawing'])+'<p>'+esc(i['prompt'])+'</p>')
                s.append('<div class="'+('draw-space' if i['drawing']=='blank' else 'answer-space')+'" contenteditable="true"></div>')
            s.append('<small>기록: □ 독립 설명 □ 도움 후 설명 □ 다시 확인 □ 미학습 □ 미실시<br>사용한 도움 / 실제로 말한 내용: ____________________________________</small></article>')
        s.append('</div>')
    s.append('<section><h3>출처와 범위</h3>')
    for v in SOURCES:s.append('<p><a href="'+v['url']+'">'+esc(v['title'])+'</a>'+(' · '+esc(v['note']) if v.get('note') else '')+'</p>')
    s.append('<p>문항·지문·도표는 자체 제작입니다. EBS 문항을 복제하지 않았습니다. 영어 주제는 학교에서 배운 표현을 확인하여 선택합니다. 이 파일은 입력 내용을 자동 저장하지 않습니다.</p></section></main><script>document.querySelector("#subject").onchange=e=>document.querySelectorAll(".unit").forEach(x=>x.style.display=e.target.value==="전체"||x.dataset.subject===e.target.value?"":"none");</script></html>')
    (OUT/name).write_text(''.join(s),encoding='utf-8')

